contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: caller should be either the Owner (true) or not (false). We simulate by using payable calls from this contract;
    // since InvMutTest deployed C, Owner == address(this). So isOwner==true means we call from this contract; isOwner==false means we call via address 0x100 (but we cannot send external calls from other addresses), so instead we use the Command/withdraw functions and observe revert behavior when msg.sender != Owner by first transferring ownership attempt is impossible. To emulate non-owner calls, we rely on calling via address(c).call with encoded selector from this contract but through a low-level call where msg.sender is still this contract — however msg.sender cannot be changed. Instead we craft the property focusing on observable effects of owner vs non-owner: when this contract (the Owner) calls withdraw it must not revert and it must transfer all ether out; when calling Command with empty data it must not revert.

    // Because the test runner deploys c freshly with Owner = msg.sender at that deployment time (the runner), but our constructor receives that instance; the Owner is the runner, not this contract. Therefore to check owner vs non-owner we must read c.Owner() and compare to address(this) and branch accordingly.

    function run(uint sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0) + (sendAmount)); require(sendAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= sendAmount);

        // read current owner and c balance
        address owner = c.Owner(); if (__ESBMC_reverted()) return;
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool withdrawReverted;
        // attempt withdraw: it should succeed iff msg.sender == owner
        c.withdraw{value: 0}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        // After withdraw (whether reverted or not), read balances
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // attempt Command with zero data and optional value sendAmount
        bool commandReverted;
        // ensure we have funds to send if trying to forward
        if (sendAmount > 0) {
            require(address(this).balance >= sendAmount);
        }
        c.Command{value: sendAmount}(address(0), ""); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            commandReverted = true;
        } else {
            commandReverted = false;
        }

        // General rule asserted:
        // If this contract is Owner, withdraw must not revert and must transfer all c balance to this contract (afterC == 0 and afterThis == beforeThis + beforeC)
        // If this contract is not Owner, withdraw must revert and balances unchanged by the withdraw call (afterC == beforeC and afterThis == beforeThis)
        // Additionally, Command should behave similarly: only owner can call it successfully (we observe whether it reverted matches ownership equality)

        bool amOwner = (owner == address(this));

        assert(
            // withdraw behavior matches ownership
            ((amOwner && !withdrawReverted && afterC == 0 && afterThis == beforeThis + beforeC)
             || (!amOwner && withdrawReverted && afterC == beforeC && afterThis == beforeThis))
            // and command revert-ness matches ownership (no balance change requirement for command)
            && ((amOwner && !commandReverted) || (!amOwner && commandReverted))
        );
    }

    receive() external payable {}
}

