// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _run(uint256 sendAmount) internal {
        sendAmount = bound(sendAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        address owner;
        try c.Owner() returns (address __r) { owner = __r; } catch { return; }
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        bool withdrawReverted;
        try c.withdraw{value: 0}() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        bool commandReverted;
        if (sendAmount > 0) {
            require(address(this).balance >= sendAmount);
        }
        try c.Command{value: sendAmount}(address(0), "") {
            commandReverted = false;
        } catch {
            commandReverted = true;
        }
        bool amOwner = (owner == address(this));
        assertTrue(((amOwner && !withdrawReverted && afterC == 0 && afterThis == beforeThis + beforeC)
             || (!amOwner && withdrawReverted && afterC == beforeC && afterThis == beforeThis))
            // and command revert-ness matches ownership (no balance change requirement for command)
            && ((amOwner && !commandReverted) || (!amOwner && commandReverted)));
    }

    function testFuzz_run(uint256 sendAmount) public {
        _run(sendAmount);
    }

    receive() external payable {}
}
